{
        auto_https off
}

:8443 {
        # 🔒 全局帳密防線
        basic_auth {
                xiaye $2b$14$kAfkIJk2pesrjGKC23A2a.UuUGCzg27xEmBr8mxbQB90NSnwZ9dKW
        }

        # ---------------------------------------------------------
        # 【OpenHands 入口：注入 X-Forwarded-For 與真實 Host 憑證】
        # ---------------------------------------------------------
        handle /openhands* {
                uri strip_prefix /openhands
                reverse_proxy 127.0.0.1:8001 {
                        header_up Host {http.request.host}
                        header_up X-Real-IP {http.request.remote}
                        header_up X-Forwarded-For {http.request.remote}
                }
        }
        handle /幹媽的神隊友來了* {
